#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
mod model;mod engine;mod vault;
use engine::{Engine,Shared};use model::Project;
use std::{path::PathBuf,sync::{Arc,Mutex}};
use tauri::{Manager,State};
type R<T>=Result<T,String>;
#[tauri::command]fn snapshot(state:State<Shared>)->R<serde_json::Value>{Ok(state.lock().map_err(|e|e.to_string())?.snapshot())}
#[tauri::command]fn save_project(project:Project,state:State<Shared>)->R<serde_json::Value>{let mut s=state.lock().map_err(|e|e.to_string())?;s.save(project)?;Ok(s.snapshot())}
#[tauri::command]async fn import_media(state:State<'_,Shared>)->R<serde_json::Value>{let shared=state.inner().clone();tauri::async_runtime::spawn_blocking(move||{if let Some(files)=rfd::FileDialog::new().add_filter("Medya/LUT",&["mp4","mov","mkv","webm","avi","wav","mp3","flac","cube"]).pick_files(){let mut s=shared.lock().map_err(|e|e.to_string())?;for f in files{s.import(&f)?;}}let s=shared.lock().map_err(|e|e.to_string())?;Ok(s.snapshot())}).await.map_err(|e|e.to_string())?}
#[tauri::command]fn import_path(path:String,state:State<Shared>)->R<serde_json::Value>{let mut s=state.lock().map_err(|e|e.to_string())?;if !s.evidence{return Err("Test komutu kapalı".into());}s.import(&PathBuf::from(path))?;Ok(s.snapshot())}
#[tauri::command]fn open_project(state:State<Shared>)->R<serde_json::Value>{let mut s=state.lock().map_err(|e|e.to_string())?;if let Some(p)=rfd::FileDialog::new().add_filter("Proje",&["json"]).pick_file(){let data=std::fs::read(p).map_err(|e|e.to_string())?;if data.len()>2_000_000{return Err("Proje çok büyük".into());}let p:Project=serde_json::from_slice(&data).map_err(|e|e.to_string())?;s.save(p)?;}Ok(s.snapshot())}
#[tauri::command]fn export_project(project:Project,kind:String,state:State<Shared>)->R<String>{engine::enqueue(state.inner().clone(),project,kind)}
#[tauri::command]fn cancel_job(id:String,state:State<Shared>)->R<String>{let mut s=state.lock().map_err(|e|e.to_string())?;let j=s.jobs.iter_mut().find(|j|j.id==id).ok_or("İş yok")?;if j.status=="completed"||j.status=="failed"{return Ok("İş bitmiş".into());}j.cancelled=true;j.status="cancelled".into();if let Some(child)=s.children.get(&id){child.lock().map_err(|e|e.to_string())?.kill().map_err(|e|e.to_string())?;}Ok("İptal edildi".into())}
#[tauri::command]fn save_output(id:String,state:State<Shared>)->R<String>{let s=state.lock().map_err(|e|e.to_string())?;let j=s.jobs.iter().find(|j|j.id==id&&j.status=="completed").ok_or("Çıktı hazır değil")?;if let Some(p)=rfd::FileDialog::new().set_file_name("Kurgu-Atolyesi.mp4").save_file(){std::fs::copy(&j.file,p).map_err(|e|e.to_string())?;}Ok("Çıktı kaydedildi".into())}
#[tauri::command]fn configure_hub(token:String,state:State<Shared>)->R<String>{if token.len()>512||token.contains(['\r','\n']){return Err("Token biçimi geçersiz".into());}vault::write(&token)?;state.lock().map_err(|e|e.to_string())?.hub_token=token;Ok("Hub anahtarı Windows kimlik kasasına kaydedildi".into())}
#[tauri::command]async fn mymind(prompt:String,approved:bool,state:State<'_,Shared>)->R<serde_json::Value>{if !approved||prompt.len()>16000||prompt.trim().is_empty(){return Err("Metin ve açık onay gerekli".into());}let token=state.lock().map_err(|e|e.to_string())?.hub_token.clone();if token.is_empty(){return Err("Hub anahtarı yapılandırılmadı".into());}tauri::async_runtime::spawn_blocking(move||{let agent=ureq::AgentBuilder::new().redirects(0).timeout(std::time::Duration::from_secs(60)).build();let response=agent.post("http://127.0.0.1:47632/v1/chat/completions").set("Authorization",&format!("Bearer {token}")).send_json(serde_json::json!({"model":"mymind-lite","messages":[{"role":"user","content":prompt}],"stream":false,"max_tokens":512})).map_err(|_|"Hub yanıt vermedi; izin ve bağlantıyı kontrol edin".to_string())?;let data:serde_json::Value=response.into_json().map_err(|e|e.to_string())?;let text=data["choices"][0]["message"]["content"].as_str().ok_or("Metin yanıtı yok")?;Ok(serde_json::json!({"text":text,"source":"PluginLabs Hub · MyMind"}))}).await.map_err(|e|e.to_string())?}
#[tauri::command]async fn demo_project(state:State<'_,Shared>)->R<serde_json::Value>{let shared=state.inner().clone();tauri::async_runtime::spawn_blocking(move||{let mut s=shared.lock().map_err(|e|e.to_string())?;let file=s.root.join("demo-source.mp4");engine::run("ffmpeg",&["-v","error","-y","-f","lavfi","-i","testsrc2=s=960x540:r=30:d=6","-f","lavfi","-i","sine=frequency=440:duration=6","-c:v","libx264","-threads","2","-pix_fmt","yuv420p","-c:a","aac","-shortest"].iter().map(|s|s.to_string()).chain(std::iter::once(file.to_string_lossy().into())).collect::<Vec<_>>(),None)?;let m=s.import(&file)?;let p:Project=serde_json::from_value(serde_json::json!({"version":2,"name":"PluginLabs · Rust medya stüdyosu","width":1920,"height":1080,"fps":30,"clips":[{"id":"demo-video","mediaId":m.id,"start":0,"in":0,"duration":6,"layer":0,"volume":0.4,"fade":0.3,"brightness":0,"contrast":1.1,"saturation":1.1,"blur":0,"x":0,"y":0,"scale":1,"opacity":1,"speed":1,"keyframes":[],"nodes":[]}],"subtitles":[{"text":"Kurgu Atölyesi · Rust çekirdeği","start":0.5,"duration":4.5}]})).map_err(|e|e.to_string())?;s.save(p)?;Ok(s.snapshot())}).await.map_err(|e|e.to_string())?}
fn main(){tauri::Builder::default().setup(|app|{let args:Vec<_>=std::env::args().collect();let evidence=args.iter().any(|a|a=="--evidence");let root=if evidence{args.iter().position(|a|a=="--data-dir").and_then(|i|args.get(i+1)).map(PathBuf::from).unwrap_or(app.path().app_data_dir()?)}else{app.path().app_data_dir()?};if evidence{app.asset_protocol_scope().allow_directory(&root,true)?;}let mut engine=Engine::new(root,evidence).map_err(std::io::Error::other)?;engine.hub_token=std::env::var("KURGU_HUB_TOKEN").ok().or_else(vault::read).unwrap_or_default();app.manage(Arc::new(Mutex::new(engine)));if let Some(window)=app.get_webview_window("main"){if !evidence{window.show()?;}}Ok(())}).invoke_handler(tauri::generate_handler![snapshot,save_project,import_media,import_path,open_project,export_project,cancel_job,save_output,demo_project,configure_hub,mymind]).run(tauri::generate_context!()).expect("Kurgu Atölyesi başlatılamadı");}
